internal abstract class UPSItemBasePriceCalcJob extends RunBaseBatch
{
    ItemId                      itemId;
    InventDimId                 inventDimId;
    UPSBasePriceVersionId       basePriceVersionId;
    InventSiteId                siteId;
    TransDate                   calcDate;
    UPSBasePriceCalcPriceCalcId priceCalcId;

    UPSBasePriceCalcItem        basePriceCalcItem;
    UPSBasePriceRawData         basePriceRawData;
    boolean                     showItemPriceCalcFormAfterRun;

    // Transfer
    NoYes                       purchPriceTransfer;
    NoYes                       salesPriceTransfer;
    NoYes                       costPriceTransfer;

    UPSCalcBasePriceVersionUpdate calcBasePriceVersionUpdate;

    // Where used update
    UPSBasePriceCalcWhereUsedUpdate      basePriceCalcWhereUsedUpdate;

    UPSBasePriceVersion basePriceVersion;

    #Define.CurrentVersion(99)
    #LOCALMACRO.CurrentList
        CalcDate,
        purchPriceTransfer,
        costPriceTransfer,
        salesPriceTransfer,
        basePriceVersionId,
        calcBasePriceVersionUpdate,
        siteId,
        basePriceCalcWhereUsedUpdate,
        itemId,
        inventDimId,
        priceCalcId,
        basePriceVersion
    #ENDMACRO

}

