InventDimId inventDimIdSite()
{
    InventDim   inventDimSite;

    inventDimSite.InventSiteId = this.parmSiteId();
    return InventDim::findOrCreate(inventDimSite).InventDimId;
}

boolean showItem()
{
    return true;
}

void new()
{
    super();

    calcDate                    = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    costPriceTransfer           = NoYes::Yes;
    purchPriceTransfer          = NoYes::Yes;
    salesPriceTransfer          = NoYes::Yes;
    basePriceVersionId          = '';
    calcBasePriceVersionUpdate  = UPSCalcBasePriceVersionUpdate::Overwrite;

}

public container pack()
{
    container packed = [#CurrentVersion,#CurrentList];

    return packed;
}

public Object dialog()
{
    return this.dialogInternal(Dialog::newFormnameRunbase(formStr(UPSItemBasePriceCalcDialog), this));
}

protected UPSBasePriceCalcItem constructbasePriceCalcItem()
{
    UPSBasePriceCalcItem basePriceCalcItemLocal;

    basePriceCalcItemLocal = UPSBasePriceCalcItem::newItem(
        basePriceRawData,
        itemId,
        inventDimId,
        '',
        calcDate,
        basePriceVersionId,
        calcBasePriceVersionUpdate,
        purchPriceTransfer,
        salesPriceTransfer,
        costPriceTransfer);

    return basePriceCalcItemLocal;
}

void run()
{
    this.runBasePriceCalculation();
}

protected void runBasePriceCalculation()
{
    #OCCRetryCount

    setPrefix(UPSItemBasePriceCalcJob::description());

    try
    {
        ttsbegin;

        basePriceCalcItem = this.constructbasePriceCalcItem();

        if (basePriceCalcItem != null)
        {
            // This will call calculation and infolog on the basePriceCalcItem object
            this.calcBasePriceCalcItem();

            if (basePriceCalcItem.parmBasePriceCalcTable())
            {
                // transfer calculation data to inventItemPrice
                this.updateItemPriceFromCalcData(basePriceCalcItem);
            }
        }

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        if (this.calculateAll())
        {
            throw error(strFmt("@SYS24365", itemId), '', InventTable::infoActionItemId(itemId));
        }
        else
        {
            throw error("@SYS21990");
        }
    }
}

protected void calcBasePriceCalcItem()
{
    basePriceCalcItem.calc();
}

protected void updateItemPriceFromCalcData(UPSBasePriceCalcItem _basePriceCalcItem)
{
    UPSBasePriceCalcUpdateItem basePriceCalcUpdateItem = this.initCalcUpdateItem(_basePriceCalcItem);
    basePriceCalcUpdateItem.run();
}

protected UPSBasePriceCalcUpdateItem initCalcUpdateItem(UPSBasePriceCalcItem _basePriceCalcItem)
{
    UPSBasePriceCalcUpdateItem basePriceCalcUpdateItem = UPSBasePriceCalcUpdateItem::construct();

    basePriceCalcUpdateItem.initFromBuffer(_basePriceCalcItem.parmBasePriceCalcTable());

    basePriceCalcUpdateItem.initParameters(
                                    purchPriceTransfer,
                                    costPriceTransfer,
                                    salesPriceTransfer,
                                    basePriceVersionId,
                                    calcDate,
                                    siteId);

    return basePriceCalcUpdateItem;
}

boolean calculateAll()
{
    return false;
}

static UPSItemBasePriceCalcJob construct(Args args)
{
    return null;
}

static ClassDescription description()
{
    return "@SYS343262";
}

static void main(Args args)
{
    if (!args)
    {
        throw error(strFmt("@SYS23686", formStr(UPSBasePriceVersion)));
    }

    UPSItemBasePriceCalcJob basePriceCalc = UPSItemBasePriceCalcJob::newBasePriceCalcJobFromArgs(args);

    if (basePriceCalc.prompt())
    {
        using (SysErrorMessageHelpScope scope = SysErrorMessageHelpScope::newErrorContext(args))
        {
            basePriceCalc.runOperation();
        }

        basePriceCalc.openItemPriceCalcForm(args.caller());
    }
}

protected void openItemPriceCalcForm(Object _caller)
{
    if (this.parmShowItemPriceCalcFormAfterRun())
    {
        Args argsItemPriceCalcForm = new Args();
        argsItemPriceCalcForm.caller(_caller);
        argsItemPriceCalcForm.record(InventTable::find(this.parmItemId()));

        FormRun formRunItemPriceCalcForm = new MenuFunction(menuitemDisplayStr(UPSItemBasePrice), MenuItemType::Display).create(argsItemPriceCalcForm);
        formRunItemPriceCalcForm.run();
    }
}

public boolean unpack(container packedClass)
{
    Integer  version    = conPeek(packedClass,1);

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            return true;
        default:
            return false;
    }
}

static UPSItemBasePriceCalcJob newBasePriceCalcJobFromArgs(Args args)
{
    UPSItemBasePriceCalcJob         basePriceCalc;
    UPSIItemBasePriceCalcIRunnable  calcFormRun;

    calcFormRun = args.caller();
    basePriceCalc = UPSItemBasePriceCalcJob::newAll(calcFormRun.basePriceVersion());

    return basePriceCalc;
}

static UPSItemBasePriceCalcJob newAll(UPSBasePriceVersion _basePriceVersion)
{
    UPSItemBasePriceCalcJob_All  basePriceCalc = UPSItemBasePriceCalcJob_All::construct();

    basePriceCalc.getLast();
    basePriceCalc.parmBasePriceVersionId(_basePriceVersion.VersionId);
    basePriceCalc.parmSiteId(_basePriceVersion.InventSiteId);
    basePriceCalc.parmInventDimId(basePriceCalc.inventDimIdSite());

    return basePriceCalc;
}
